S = [('Inhalt', [('Vorlesung 4: *Warum* bewegt sich etwas? → *Dynamik*', 'Willkommen zu Vorlesung vier. Bisher haben wir beschrieben, wie sich etwas bewegt. Das war die Kinematik. Jetzt fragen wir, warum es sich so bewegt. Das ist die Dynamik.'), ('Kraft und Impuls · die *drei Newtonschen Axiome*', 'Dazu brauchen wir zwei Größen, die Kraft und den Impuls, und die drei Grundgesetze von Isaac Newton.')]), ('Bewegung hat eine Ursache', [('Bewegungsänderungen haben eine *Ursache*: die *Kraft F*', 'Bewegungen laufen nicht von selbst ab. Sie haben ihre Ursache in der Einwirkung anderer Körper. Diese Einwirkung beschreibt man mit der Vektorgröße Kraft.'), ('Galilei: *ohne Kraft* → Ruhe oder *geradlinig gleichförmig*', 'Schon Galileo Galilei hat erkannt: Ein Körper, auf den keine Kraft wirkt, bleibt in Ruhe oder bewegt sich geradlinig und gleichförmig weiter. Das nennt man Trägheitsprinzip.'), ('Alltag: alles bleibt stehen → verborgene Kraft *Reibung*', 'Im Alltag scheint das falsch: Ein angestoßener Körper bleibt irgendwann liegen. Der Grund ist eine verborgene Kraft aus der Umgebung, die Reibung. Ein Eishockey-Puck auf glattem Eis rutscht dagegen sehr lange.')]), ('Kraft, Masse, Beschleunigung', [('Kräfte verursachen *Beschleunigung*', 'Kräfte rufen Beschleunigungen hervor. Darüber kann man Kräfte messen.'), ('Gleiche Kraft, *verschiedene Körper* → verschiedene Beschleunigung', 'Für einen bestimmten Körper ist die Beschleunigung proportional zur Kraft. Verschiedene Körper reagieren aber auf dieselbe Kraft verschieden stark.'), ('Folie: „entgegenwirkenden“ – gemeint ist die *einwirkende* Kraft', 'Kleiner Hinweis zur Folie: Dort steht entgegenwirkende Kraft. Gemeint ist die einwirkende Kraft, also die Kraft, die den Körper beschleunigt.'), ('Widerstand gegen Bewegungsänderung = *Trägheit* → *Masse m*', 'Diesen Widerstand gegen eine Bewegungsänderung nennt man Trägheit. Er wird durch die Masse erfasst: Je größer die Masse, desto schwerer lässt sich der Körper beschleunigen.'), ('*a = F / m* · Einheit: *1 N = 1 kg·m/s²*', 'Zusammengefasst: Beschleunigung gleich Kraft durch Masse. Kräfte misst man in Newton. Ein Newton ist genau die Kraft, die ein Kilogramm mit einem Meter pro Sekunde Quadrat beschleunigt.')]), ('Der Impuls', [('Kraft über eine Zeit → *Geschwindigkeit ändert sich*', 'Wirkt eine Kraft eine Zeit lang auf einen frei beweglichen Körper, ändert sich seine Geschwindigkeit. Je kleiner die Masse, desto größer die Änderung.'), ('*Impuls p = m · v* – Masse mal Geschwindigkeit', 'Deshalb fasst man Masse und Geschwindigkeit zu einer Größe zusammen: dem Impuls, p gleich m mal v.'), ('Beispiel: Tischtennisball vs. Bowlingkugel bei *5 m/s*', 'Das erklärt das Beispiel auf der Folie: Ein Tischtennisball hat etwa zwei Komma sieben Gramm, eine Bowlingkugel etwa sieben Kilogramm. Beide mit fünf Metern pro Sekunde: Der Ball hat null Komma null eins drei fünf, die Kugel fünfunddreißig Kilogramm mal Meter pro Sekunde. Das ist gut zweitausendfünfhundertmal so viel Wucht.')]), ('Impuls als Vektor', [('p hat die *Richtung von v* · Einheit *kg·m/s*', 'Die Masse ist ein Skalar, also eine reine Zahl ohne Richtung. Deshalb zeigt der Impuls immer in Richtung der Geschwindigkeit. Seine Einheit ist Kilogramm mal Meter pro Sekunde.'), ('Zeitableitung bei m konstant: *ṗ = m · a* · Einheit *kg·m/s²*', 'Leitet man den Impuls nach der Zeit ab und die Masse bleibt gleich, erhält man Masse mal Beschleunigung. Die Einheit ist dann Kilogramm mal Meter pro Sekunde Quadrat, also Newton. Genau das braucht gleich das zweite Axiom.')]), ('Die drei Newtonschen Axiome', [('1. *Trägheitsprinzip*: ohne Kraft keine Bewegungsänderung', 'Isaac Newton hat die ganze Mechanik auf drei Grundsätzen aufgebaut. Erstens das Trägheitsprinzip: Ohne Kraft bleibt ein Körper in Ruhe oder in gleichförmiger Bewegung.'), ('2. *Aktionsprinzip*: *F = ṗ* – Kraft = Impulsänderung pro Zeit', 'Zweitens das Aktionsprinzip: Die Kraft ist gleich der zeitlichen Änderung des Impulses.'), ('3. *Reaktionsprinzip*: A auf B mit F → B auf A mit *−F*', 'Drittens das Reaktionsprinzip: Drückt ein Körper A mit einer Kraft auf B, drückt B mit der gleich großen, entgegengesetzten Kraft zurück. Kurz: actio gleich reactio.')]), ('1. Axiom: Trägheitsprinzip', [('*F = 0 → v = const* · Ruhe ist der Sonderfall v = 0', 'Das erste Axiom heißt auch galileisches Trägheitsprinzip. In einer Formel: Ist die Kraft null, bleibt die Geschwindigkeit konstant. Ruhe ist nur der Sonderfall Geschwindigkeit null.'), ('Nicht direkt prüfbar: *Reibung* lässt sich nie ganz ausschalten', 'Direkt im Experiment prüfen lässt sich das nicht, weil man Reibung und andere Einflüsse nie ganz ausschalten kann.'), ('Merke: *jede* Änderung von v hat eine *Kraft* als Ursache', 'Umgekehrt gilt: Wird ein Körper schneller, langsamer oder ändert er seine Richtung, dann wirkt eine Kraft. Daran erkennt man in jeder Aufgabe, ob Kräfte im Spiel sind.')]), ('2. Axiom: Kraft und Beschleunigung', [('Konstante Kraft → *gleichmäßig beschleunigte* Bewegung', 'Greift eine konstante Kraft an, bewegt sich der Körper gleichmäßig beschleunigt. Das bekannteste Beispiel ist der freie Fall.'), ('Doppelte Kraft → *doppelte Beschleunigung*: F ~ a', 'Verdoppelt man die Kraft, verdoppelt sich die Beschleunigung. Kraft und Beschleunigung sind proportional, und der Proportionalitätsfaktor ist die Masse: F durch a gleich m.'), ('Bild: Wagen m_1 auf dem Tisch, Gewicht m_2 zieht über die Rolle', 'Das Bild zeigt einen typischen Versuch: Ein Wagen mit der Masse m eins steht reibungsfrei auf dem Tisch. Ein Gewicht mit der Masse m zwei hängt am Seil über die Rolle und zieht ihn.'), ('Beispiel m_1 = 2 kg, m_2 = 1 kg → *a = 3,27 m/s²*', 'Ein Zahlenbeispiel: m eins zwei Kilogramm, m zwei ein Kilogramm. Die antreibende Kraft ist die Gewichtskraft des hängenden Körpers: ein Kilogramm mal neun Komma acht eins, also neun Komma acht eins Newton. Beschleunigt werden aber beide Massen zusammen, drei Kilogramm. Also a gleich neun Komma acht eins durch drei, das sind drei Komma zwei sieben Meter pro Sekunde Quadrat.')]), ('Grundgesetz der Dynamik', [('Masse = Maß für die *Trägheit* eines Körpers', 'Die Masse beschreibt, wie stark sich ein Körper gegen eine Änderung seiner Bewegung wehrt. Sie ist ein Maß für seine Trägheit.'), ('*F = m · a* – Grundgesetz der Dynamik', 'Daraus folgt das Grundgesetz der Dynamik: F gleich m mal a. Das ist die wichtigste Formel der ganzen Mechanik.'), ('Folgerungen: *Gewichtskraft* · träge/schwere Masse · *Zentripetalkraft*', 'Drei Folgerungen schauen wir uns gleich an: die Gewichtskraft, die Gleichheit von träger und schwerer Masse und die Zentripetalkraft auf der Kreisbahn.')]), ('Masse oder Gewicht?', [('*Masse* in kg – überall gleich · *Gewicht(skraft)* in N – ortsabhängig', 'Ein häufiger Fehler: Masse und Gewicht verwechseln. Die Masse in Kilogramm ist überall gleich. Die Gewichtskraft in Newton hängt davon ab, wie stark die Gravitation am Ort ist.'), ('Genauer: Masse = *Menge Materie* und *Trägheit* – „schwer“ ist das Gewicht', 'Kleine Präzisierung zur ersten Zeile der Folie: Die Masse sagt, wie viel Materie ein Körper hat und wie träge er ist. Wie schwer er sich anfühlt, ist eigentlich seine Gewichtskraft.'), ('Beispiel 70 kg: Erde *687 N*, Mond *113 N* – Masse bleibt *70 kg*', 'Ein Beispiel: Ein Mensch mit siebzig Kilogramm hat auf der Erde die Gewichtskraft siebzig mal neun Komma acht eins, also rund sechshundertsiebenundachtzig Newton. Auf dem Mond ist die Fallbeschleunigung nur eins Komma sechs zwei Meter pro Sekunde Quadrat. Dort wiegt er nur hundertdreizehn Newton, hat aber weiterhin siebzig Kilogramm Masse.')]), ('Gewichtskraft', [('Masse bestimmt *Trägheit* und *Schwere*', 'Die Masse bestimmt nicht nur die Trägheit eines Körpers, sondern auch seine Schwere, also wie stark ihn die Erde anzieht.'), ('Faden spannen → *Gewichtskraft F_G* · Faden durch → *g = 9,81 m/s²*', 'Hängt ein Körper am Faden, spannt er ihn mit der Gewichtskraft. Schneidet man den Faden durch, fällt er frei mit der Erdbeschleunigung g gleich neun Komma acht eins Meter pro Sekunde Quadrat.'), ('*F_G = m · g* – 1 kg wiegt *9,81 N ≈ 10 N*', 'Daraus folgt die Formel F G gleich m mal g. Merkhilfe: Ein Kilogramm hat eine Gewichtskraft von neun Komma acht eins, also knapp zehn Newton.')]), ('Zentripetalkraft', [('Kreisbahn braucht *a_r = ω² r* zum Mittelpunkt', 'Aus Vorlesung drei wissen wir: Auf einer Kreisbahn braucht ein Körper die Radialbeschleunigung omega Quadrat mal r. Das Minus in der Formel heißt nur: Sie zeigt zum Mittelpunkt.'), ('Mit F = m a: *F_r = m ω² r* – die *Zentripetalkraft*', 'Mit dem Grundgesetz F gleich m a wird daraus eine Kraft, die zum Mittelpunkt zeigt: die Zentripetalkraft, m mal omega Quadrat mal r.'), ('Beispiel 0,2 kg, r = 0,5 m, ω = 4 1/s → *F_r = 1,6 N*', 'Ein Beispiel: Eine Kugel mit zweihundert Gramm kreist an einem fünfzig Zentimeter langen Seil mit omega gleich vier pro Sekunde. Dann ist die Beschleunigung sechzehn mal null Komma fünf, also acht Meter pro Sekunde Quadrat, und die Kraft null Komma zwei mal acht gleich eins Komma sechs Newton. Dieses Beispiel kommt in Vorlesung fünf wieder.')]), ('3. Axiom: actio = reactio', [('*F_12 = −F_21* – Kraft und Gegenkraft', 'Das dritte Axiom: Übt Körper eins auf Körper zwei die Kraft F eins zwei aus, wirkt Körper zwei mit F zwei eins zurück. Beide sind gleich groß und entgegengesetzt.'), ('Achtung: Kraft und Gegenkraft wirken auf *verschiedene Körper* – sie heben sich *nicht* auf', 'Achtung, die fett gedruckte Zeile ist missverständlich. Kraft und Gegenkraft greifen an zwei verschiedenen Körpern an. Deshalb halten sie sich nicht im Gleichgewicht und heben sich nicht auf. Gleichgewicht gibt es nur zwischen Kräften am selben Körper. Vorlesung fünf sagt das ausdrücklich.'), ('Welche „Kraft“ und welche „Gegenkraft“ ist: *egal*', 'Welche der beiden man Kraft und welche Gegenkraft nennt, ist egal. Sie sind gleichberechtigt.')]), ('Wechselwirkung', [('Immer *zwei Körper*: Kräfte sind *Wechselwirkungen*', 'An jeder Kraft sind immer zwei Körper beteiligt. Sie stehen in Wechselwirkung. Eine einzelne Kraft ist nur die Hälfte davon.'), ('Beispiel: Buch auf Tisch · Rakete stößt Gas aus', 'Zwei Beispiele: Ein Buch drückt auf den Tisch, der Tisch drückt das Buch nach oben. Eine Rakete drückt die Abgase nach hinten, die Abgase drücken die Rakete nach vorn. So fliegt sie auch im leeren Weltall.')]), ('Inertialsysteme', [('*Inertialsystem*: kräftefreier Körper ruht oder bewegt sich gleichförmig', 'Das erste Axiom gilt nicht in jedem Bezugssystem. Ein Inertialsystem ist ein Bezugssystem, in dem ein kräftefreier Körper ruht oder sich gleichförmig geradeaus bewegt.'), ('System B fährt mit *v_BA = const* → auch ein Inertialsystem', 'Das Bild kennst du aus Vorlesung drei: B bewegt sich mit konstanter Geschwindigkeit gegenüber A. Dann messen beide dieselbe Beschleunigung. Ist P kräftefrei, ist sie für beide null. Also sind beide Inertialsysteme.'), ('In Inertialsystemen *keine Scheinkräfte* (z. B. Fliehkraft)', 'In Inertialsystemen gelten die Newtonschen Axiome ohne Zusatz. Es tauchen keine Scheinkräfte auf. Die Fliehkraft, die du im Karussell spürst, gibt es nur im mitdrehenden, also beschleunigten System.')]), ('Impuls eines Teilchens', [('*p = m · v* · Einheit *kg·m/s*', 'Hier noch einmal der Impuls: p gleich m mal v, Einheit Kilogramm mal Meter pro Sekunde.'), ('m konstant: *ṗ = m · a* – Einheit kg·m/s² (Folie: [p] statt [ṗ])', 'Bei konstanter Masse ist die Ableitung des Impulses Masse mal Beschleunigung. Die untere Einheit gehört zu p Punkt, auf der Folie steht versehentlich nur p.'), ('Ohne äußere Kräfte: *Gesamtimpuls bleibt erhalten*', 'Der Text links meint: Wirken keine äußeren Kräfte, heben sich die inneren Kräfte paarweise auf, wegen actio gleich reactio. Dann bleibt der Gesamtimpuls konstant. Das ist die Impulserhaltung.')]), ('2. Axiom mit mehreren Kräften', [('Mehrere Kräfte → *Vektorsumme* F_res', 'Wirken mehrere Kräfte, zählt nur ihre Vektorsumme, die resultierende Kraft. Im Bild ergeben F eins und F zwei zusammen die rote Kraft F res.'), ('*ṗ = m a = F_res* · [F] = kg·m/s² = *N*', 'Das zweite Axiom lautet dann: p Punkt gleich m mal a gleich F res. Die Beschleunigung zeigt also in Richtung der resultierenden Kraft.')]), ('Masse vergleichen', [('a ~ F und *a ~ 1/m*', 'Die Beschleunigung ist proportional zur Kraft und umgekehrt proportional zur Masse. Je größer die Masse, desto größer die Trägheit.'), ('Gleiche Kraft: *m_1 / m_2 = a_2 / a_1*', 'Wirkt dieselbe Kraft auf zwei Körper, verhalten sich die Massen umgekehrt wie die Beschleunigungen. So kann man Massen vergleichen, ohne sie zu wiegen.'), ('Beispiel F = 10 N: 2 kg → *5 m/s²*, 5 kg → *2 m/s²*', 'Beispiel: Zehn Newton auf zwei Kilogramm ergeben fünf Meter pro Sekunde Quadrat, auf fünf Kilogramm nur zwei. Probe: zwei durch fünf ist gleich zwei durch fünf.')]), ('actio = reactio im Bild', [('*F_AB = −F_BA* – gleich groß, entgegengesetzt', 'Das Bild zeigt das dritte Axiom: A zieht B an, B zieht A gleich stark zurück. F A B gleich minus F B A.'), ('Gleiche Kraft, *verschiedene Beschleunigung*: 100 N auf 50 kg und 80 kg', 'Gleiche Kräfte heißt aber nicht gleiche Wirkung. Zwei Eisläufer stoßen sich mit hundert Newton ab. Der mit fünfzig Kilogramm wird mit zwei Meter pro Sekunde Quadrat beschleunigt, der mit achtzig Kilogramm nur mit eins Komma zwei fünf.'), ('Vorlesung 4 geschafft – weiter mit den *Kraftgesetzen*', 'Damit hast du die Grundgesetze. In Vorlesung fünf geht es darum, welche Kräfte es konkret gibt: Gravitation, Normalkraft, Reibung, Luftwiderstand und Seilkraft.')])]
